/*
 * A042451  Denominators of continued fraction convergents to sqrt(753).
 * https://oeis.org/A042451
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) is the denominator of the n-th convergent in the continued
 *            fraction expansion of √753. The recurrence used: q_{-1}=0,
 *            q_0=1; q_n = a_n * q_{n-1} + q_{n-2}, where a_n are the partial
 *            quotients of √753 generated by the standard continued–fraction
 *            algorithm
 * Range:     u8 n <= 1, u16 n <= 11, u32 n <= 21, u64 n <= 39, u128 n <= 80,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    const seq_t D   = (seq_t)753;
    const seq_t a0  = (seq_t)27;       /* floor(sqrt(753)) */

    if (n == 0) return (seq_t)1;       /* q_0 */

    seq_t q_prev2 = (seq_t)0;          /* q_{-1} */
    seq_t q_prev1 = (seq_t)1;          /* q_0 */

    seq_t m     = (seq_t)0;            /* m_0  */
    seq_t d     = (seq_t)1;            /* d_0  */
    seq_t a_prev = a0;                 /* a_{i-1} */

    idx_t i;
    for (i = 1; i <= n; ++i)
    {
        /* compute next m, d, a */
        seq_t m_new = d * a_prev - m;
        seq_t d_new = (D - m_new * m_new) / d;
        seq_t a_curr = (a0 + m_new) / d_new;

        /* compute denominator q_i */
        seq_t q_curr = a_curr * q_prev1 + q_prev2;

        /* update for next iteration */
        m = m_new;
        d = d_new;
        a_prev = a_curr;

        q_prev2 = q_prev1;
        q_prev1 = q_curr;
    }

    return q_prev1;
}
